import{_ as t,o as e,c as r,a2 as l}from"./chunks/framework.Crpw6aS5.js";const u=JSON.parse('{"title":"创作工具箱","description":"","frontmatter":{},"headers":[],"relativePath":"08_creative_tools/index.md","filePath":"08_creative_tools/index.md"}'),n={name:"08_creative_tools/index.md"};function s(i,a,d,o,h,c){return e(),r("div",null,[...a[0]||(a[0]=[l(`<h1 id="创作工具箱" tabindex="-1">创作工具箱 <a class="header-anchor" href="#创作工具箱" aria-label="Permalink to &quot;创作工具箱&quot;">​</a></h1><p>为视频号和公众号创作者提供的实用指南。</p><hr><h2 id="选题工具" tabindex="-1">选题工具 <a class="header-anchor" href="#选题工具" aria-label="Permalink to &quot;选题工具&quot;">​</a></h2><h3 id="从股东信中挖掘选题的路径" tabindex="-1">从股东信中挖掘选题的路径 <a class="header-anchor" href="#从股东信中挖掘选题的路径" aria-label="Permalink to &quot;从股东信中挖掘选题的路径&quot;">​</a></h3><p><strong>投资案例拆解</strong>：每年股东信都有大量真实投资案例（桑博恩地图、登普斯特、GEICO等），每个案例都是独立的深度选题。拆解路径：背景→买入逻辑→持有过程→结果→启示。</p><p><strong>概念澄清型</strong>：针对常见投资误解撰写澄清文章（如&quot;巴菲特为什么不买黄金&quot;&quot;为什么复利这么重要&quot;），以股东信原文为依据。</p><p><strong>历史对比型</strong>：将巴菲特在不同历史时期对同一问题的态度变化做纵向对比（如1990年代vs2008年对银行的态度）。</p><p><strong>金句视频型</strong>：选一句有视觉冲击力的话，配上巴菲特演讲画面或静态图片，制作15-60秒短视频。</p><h3 id="推荐选题方向" tabindex="-1">推荐选题方向 <a class="header-anchor" href="#推荐选题方向" aria-label="Permalink to &quot;推荐选题方向&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方向</th><th>示例标题</th><th>适合时长</th></tr></thead><tbody><tr><td>案例深度拆解</td><td>《1967年巴菲特花5400万买的是什么》</td><td>3-8分钟</td></tr><tr><td>概念通俗解读</td><td>《什么是浮存金，巴菲特怎么用它赚钱》</td><td>2-5分钟</td></tr><tr><td>人物故事</td><td>《让巴菲特佩服的人是怎么做生意的》</td><td>3-5分钟</td></tr><tr><td>数据可视化</td><td>《巴菲特60年收益率可视化》</td><td>1-3分钟</td></tr><tr><td>年度总结</td><td>《2024年巴菲特最新说了什么》</td><td>5-10分钟</td></tr></tbody></table><hr><h2 id="数据查询" tabindex="-1">数据查询 <a class="header-anchor" href="#数据查询" aria-label="Permalink to &quot;数据查询&quot;">​</a></h2><h3 id="伯克希尔·哈撒韦" tabindex="-1">伯克希尔·哈撒韦 <a class="header-anchor" href="#伯克希尔·哈撒韦" aria-label="Permalink to &quot;伯克希尔·哈撒韦&quot;">​</a></h3><ul><li><strong>股价历史</strong>：Yahoo Finance (BRK.A / BRK.B)、macrotrends.net</li><li><strong>SEC filings</strong>：sec.gov/cgi-bin/browse-edgar?action=getcompany&amp;CIK=BRK</li><li><strong>年报原文</strong>：berkshirehathaway.com/releases.html</li></ul><h3 id="历史收益率" tabindex="-1">历史收益率 <a class="header-anchor" href="#历史收益率" aria-label="Permalink to &quot;历史收益率&quot;">​</a></h3><ul><li>历年道指表现：investopedia.com</li><li>巴菲特合伙企业收益率（1957-1969）：见本知识库各年核心总结页</li><li>伯克希尔股价/净值历史：macrotrends.net/stocks/compare</li></ul><h3 id="持仓变化" tabindex="-1">持仓变化 <a class="header-anchor" href="#持仓变化" aria-label="Permalink to &quot;持仓变化&quot;">​</a></h3><ul><li>13F filings (SEC EDGAR)：季度更新，可追踪巴菲特调仓</li><li>伯克希尔年报：每年2月发布，含完整持仓明细</li></ul><hr><h2 id="图片素材" tabindex="-1">图片素材 <a class="header-anchor" href="#图片素材" aria-label="Permalink to &quot;图片素材&quot;">​</a></h2><h3 id="合法获取渠道" tabindex="-1">合法获取渠道 <a class="header-anchor" href="#合法获取渠道" aria-label="Permalink to &quot;合法获取渠道&quot;">​</a></h3><table tabindex="0"><thead><tr><th>资源</th><th>来源</th><th>备注</th></tr></thead><tbody><tr><td>巴菲特照片</td><td>Wikimedia Commons（部分免费）</td><td>需确认版权</td></tr><tr><td>伯克希尔年会</td><td>CNP Archives</td><td>部分公开</td></tr><tr><td>奥马哈总部</td><td>Berkshire Hathaway官网媒体资料</td><td>需申请</td></tr><tr><td>人物照片</td><td>各公司官网/新闻稿</td><td>通常可转载</td></tr></tbody></table><h3 id="工具推荐" tabindex="-1">工具推荐 <a class="header-anchor" href="#工具推荐" aria-label="Permalink to &quot;工具推荐&quot;">​</a></h3><ul><li><strong>Canva</strong> / <strong>Figma</strong>：快速制作图文封面</li><li><strong>Pexels / Unsplash</strong>：无版权股票/金融背景图</li><li><strong>DALL-E / Midjourney</strong>：生成巴菲特风格插画（避免真实人脸）</li></ul><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><ul><li>避免使用未授权的年会现场视频截图</li><li>巴菲特个人肖像权：公开演讲画面通常可合理使用</li><li>品牌Logo使用：伯克希尔/可口可乐等公司Logo用于事实陈述场景通常属合理使用</li></ul><hr><h2 id="文案模板" tabindex="-1">文案模板 <a class="header-anchor" href="#文案模板" aria-label="Permalink to &quot;文案模板&quot;">​</a></h2><h3 id="案例开头模板" tabindex="-1">案例开头模板 <a class="header-anchor" href="#案例开头模板" aria-label="Permalink to &quot;案例开头模板&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>巴菲特在XXXX年遇到了一个问题：</span></span>
<span class="line"><span>[描述当时的市场/公司背景]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>所有人都觉得[普遍误解]，</span></span>
<span class="line"><span>但他看到了[被忽视的真相]。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>后来的故事证明……</span></span></code></pre></div><h3 id="金句提炼格式" tabindex="-1">金句提炼格式 <a class="header-anchor" href="#金句提炼格式" aria-label="Permalink to &quot;金句提炼格式&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>「原话引用（附英文原文更佳）」</span></span>
<span class="line"><span></span></span>
<span class="line"><span>——年巴菲特致股东信</span></span></code></pre></div><h3 id="结尾cta模板" tabindex="-1">结尾CTA模板 <a class="header-anchor" href="#结尾cta模板" aria-label="Permalink to &quot;结尾CTA模板&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>如果你觉得这个内容有帮助，</span></span>
<span class="line"><span>欢迎关注「慢慢变富的卡尔」，</span></span>
<span class="line"><span>我们一起慢慢变富。</span></span></code></pre></div><hr><h2 id="合规提醒" tabindex="-1">合规提醒 <a class="header-anchor" href="#合规提醒" aria-label="Permalink to &quot;合规提醒&quot;">​</a></h2><h3 id="版权说明" tabindex="-1">版权说明 <a class="header-anchor" href="#版权说明" aria-label="Permalink to &quot;版权说明&quot;">​</a></h3><ul><li>巴菲特致股东信原文：伯克希尔官方发布，属公开信息，可引用</li><li>引用建议：单次引用不超过300字，并注明来源</li><li>翻译稿：需注明&quot;译文来自网络/译者&quot;，本知识库翻译仅供参考</li></ul><h3 id="原创声明建议" tabindex="-1">原创声明建议 <a class="header-anchor" href="#原创声明建议" aria-label="Permalink to &quot;原创声明建议&quot;">​</a></h3><p>发布内容时注明：</p><blockquote><p>本文部分内容参考伯克希尔·哈撒韦年报（berkshirehathaway.com），数据截止[年份]。</p></blockquote><h3 id="避免事项" tabindex="-1">避免事项 <a class="header-anchor" href="#避免事项" aria-label="Permalink to &quot;避免事项&quot;">​</a></h3><ul><li>不要将翻译稿声称是自己的原创翻译（可说明&quot;参考网络译本整理&quot;）</li><li>不要引用未确认来源的具体数据（建议交叉验证）</li><li>投资建议类内容需注意合规表述（避免&quot;买入/卖出&quot;建议）</li></ul><hr><h2 id="参考账号" tabindex="-1">参考账号 <a class="header-anchor" href="#参考账号" aria-label="Permalink to &quot;参考账号&quot;">​</a></h2><h3 id="国内" tabindex="-1">国内 <a class="header-anchor" href="#国内" aria-label="Permalink to &quot;国内&quot;">​</a></h3><table tabindex="0"><thead><tr><th>账号</th><th>内容方向</th><th>特点</th></tr></thead><tbody><tr><td>慢慢变富的卡尔（你！）</td><td>70年系统梳理</td><td>独家深度，稀缺性强</td></tr><tr><td>其他泛财经账号</td><td>金句/热点</td><td>时效性强，深度有限</td></tr></tbody></table><h3 id="国外" tabindex="-1">国外 <a class="header-anchor" href="#国外" aria-label="Permalink to &quot;国外&quot;">​</a></h3><table tabindex="0"><thead><tr><th>账号/频道</th><th>内容方向</th></tr></thead><tbody><tr><td>Berkshire Hathaway (YouTube)</td><td>官方年会完整录像</td></tr><tr><td>Value Investor Club</td><td>深度投资案例分析</td></tr><tr><td>Mr. Arkwright (YouTube)</td><td>巴菲特/芒格演讲合集</td></tr></tbody></table><h3 id="学习资源" tabindex="-1">学习资源 <a class="header-anchor" href="#学习资源" aria-label="Permalink to &quot;学习资源&quot;">​</a></h3><ul><li><strong>优质书籍</strong>：《巴菲特传》（罗杰·洛文斯坦）、《滚雪球》（爱丽丝·施罗德）、《跳着踢踏舞去上班》（玛丽·巴菲特）</li><li><strong>课程</strong>：哥伦比亚大学价值投资课程（免费，B站有搬运）</li><li><strong>论文</strong>：格雷厄姆《证券分析》原文（经典但难度高）</li></ul>`,52)])])}const b=t(n,[["render",s]]);export{u as __pageData,b as default};
